#:package System.IdentityModel.Tokens.Jwt@8.*
using System.IdentityModel.Tokens.Jwt;
using System.Text;
using Microsoft.IdentityModel.Tokens;
var oldKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes("old-key-old-key-old-key-old-key-1234"));
var newKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes("new-key-new-key-new-key-new-key-5678"));
var handler = new JwtSecurityTokenHandler();
var token = handler.WriteToken(new JwtSecurityToken(
    expires: DateTime.UtcNow.AddMinutes(5),
    signingCredentials: new SigningCredentials(oldKey, SecurityAlgorithms.HmacSha256)));
bool Valid(params SecurityKey[] keys)
{
    var p = new TokenValidationParameters
    {
        ValidateIssuer = false, ValidateAudience = false,
        IssuerSigningKeys = keys,
    };
    try { handler.ValidateToken(token, p, out _); return true; }
    catch (SecurityTokenException) { return false; }
}
Console.WriteLine(Valid(newKey, oldKey));
Console.WriteLine(Valid(newKey));

