var times = new List<double>();
for (int i = 0; i < 95; i++) times.Add(50);
for (int i = 0; i < 5; i++) times.Add(10000);
times.Sort();
var avg = times.Average();
var p99 = times[(int)Math.Ceiling(0.99 * times.Count) - 1];
Console.WriteLine($"avg={(int)avg} p99={p99}");
Console.WriteLine(avg > 2000 ? "alert-avg" : "quiet-avg");
Console.WriteLine(p99 > 2000 ? "alert-p99" : "quiet-p99");

using System.Diagnostics.Metrics;
var meter = new Meter("Crm.Orders");
var created = meter.CreateCounter<long>("orders.created");
var series = new HashSet<string>();
using var listener = new MeterListener();
listener.InstrumentPublished = (inst, l) => { if (inst.Meter.Name == "Crm.Orders") l.EnableMeasurementEvents(inst); };
listener.SetMeasurementEventCallback<long>((inst, value, tags, state) =>
{
    series.Add(string.Join(",", tags.ToArray().Select(t => $"{t.Key}={t.Value}")));
});
listener.Start();
string[] channels = { "web", "app", "web", "web", "app" };
for (int i = 1; i <= 5; i++)
    created.Add(1, new KeyValuePair<string, object?>("channel", channels[i - 1]));
Console.WriteLine("by channel: " + series.Count);
series.Clear();
for (int i = 1; i <= 5; i++)
    created.Add(1, new KeyValuePair<string, object?>("orderId", i));
Console.WriteLine("by orderId: " + series.Count);

#:package Microsoft.Extensions.Hosting@10.0.0
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
var builder = Host.CreateApplicationBuilder();
builder.Logging.ClearProviders();
builder.Services.AddHostedService<W>();
var host = builder.Build();
var life = host.Services.GetRequiredService<IHostApplicationLifetime>();
life.ApplicationStarted.Register(() => Console.WriteLine("started"));
life.ApplicationStopping.Register(() => Console.WriteLine("stopping"));
life.ApplicationStopped.Register(() => Console.WriteLine("stopped"));
await host.StartAsync();
life.StopApplication();
await host.StopAsync();
class W : IHostedService
{
    public Task StartAsync(CancellationToken ct) => Task.CompletedTask;
    public Task StopAsync(CancellationToken ct) { Console.WriteLine("worker stop"); return Task.CompletedTask; }
}

